#!/usr/bin/env node
/**
 * Draw the feature art for the 13 training categories.
 *
 *   npm run art:categories       -> web/img/cards/cat/<slug>.webp
 *
 * These are DRAWN, not generated by a model. That is the point: the basket is
 * one shared path traced from web/img/logo-mark.png, so every basket in the
 * set is the logo's basket by construction and cannot drift from it, and
 * nothing here can quietly grow a hand holding a disc.
 *
 * Geometry came from reading the logo's pixels rather than eyeballing it
 * (256x256 source): the top band spans x 54-212 over y 13-40, four chain bars
 * splay from centres 75.5/114.5/152/191 at the top to 84/117.5/149.5/182.5 at
 * the bottom, the tray is a trapezoid 51-215 narrowing to 58-208 over
 * y 157-185, and the post runs y 185-241 tapering 126-141 to 129-138.
 *
 * Composition follows the existing cards in web/img/cards: the subject sits on
 * the RIGHT and the left is kept clear, because .artcard lays a left-to-right
 * scrim over the art and puts the title on top of it.
 */
const sharp = require('sharp');
const fs = require('fs');
const path = require('path');

const OUT = path.join(__dirname, '..', 'web', 'img', 'cards', 'cat');
const W = 880, H = 495;

// web/styles/tokens.css
const INK = '#202020';
const ORANGE = '#fc6414';
const GREEN = '#2e7d57';
const PEACH = '#f7f4ef';
const DEEP = '#17392a';   // darker green, for depth behind the hill

/**
 * The logo's basket. `s` scales the 256-unit source; (x, y) is its top-left.
 * Drawn from the measurements above, so it is the same object every time.
 */
function basket(x, y, s, fill = INK) {
  const u = (n) => n * s;
  const bars = [[75.5, 84], [114.5, 117.5], [152, 149.5], [191, 182.5]];
  const bw = 8;
  const parts = [
    // top band
    `<rect x="${x + u(54)}" y="${y + u(13)}" width="${u(158)}" height="${u(27)}"
       rx="${u(13)}" fill="${fill}"/>`,
    // chains, splayed
    ...bars.map(([t, b]) =>
      `<path d="M${x + u(t - bw / 2)} ${y + u(40)} L${x + u(t + bw / 2)} ${y + u(40)}
                L${x + u(b + bw / 2)} ${y + u(157)} L${x + u(b - bw / 2)} ${y + u(157)} Z"
         fill="${fill}"/>`),
    // tray
    `<path d="M${x + u(51)} ${y + u(157)} L${x + u(215)} ${y + u(157)}
              L${x + u(208)} ${y + u(185)} L${x + u(58)} ${y + u(185)} Z" fill="${fill}"/>`,
    // post
    `<path d="M${x + u(126)} ${y + u(185)} L${x + u(141)} ${y + u(185)}
              L${x + u(138)} ${y + u(241)} L${x + u(129)} ${y + u(241)} Z" fill="${fill}"/>`,
  ];
  return parts.join('');
}

/** A disc, always flat — on the ground, in flight, or as a mark. Never held. */
const disc = (cx, cy, rx, fill = ORANGE, ry = rx * 0.34) =>
  `<ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="${fill}"/>`;

const sun = (cx, cy, r, fill = ORANGE) => `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${fill}"/>`;

const pine = (x, base, h, fill = DEEP) => {
  const w = h * 0.46;
  return `<path d="M${x} ${base - h} L${x + w / 2} ${base} L${x - w / 2} ${base} Z" fill="${fill}"/>`
    + `<rect x="${x - h * 0.03}" y="${base}" width="${h * 0.06}" height="${h * 0.07}" fill="${fill}"/>`;
};

/** The green hill the whole set stands on. */
const hill = (top = 348) =>
  `<path d="M0 ${H} L0 ${top + 40} Q ${W * 0.42} ${top - 26} ${W} ${top + 8} L${W} ${H} Z" fill="${GREEN}"/>`;

/** A flight line. `bend` < 0 curves left (backhand), > 0 curves right (forehand). */
function flight(x1, y1, x2, y2, bend, color = ORANGE, wdt = 9) {
  const mx = (x1 + x2) / 2 + bend, my = (y1 + y2) / 2 - Math.abs(bend) * 0.35;
  return `<path d="M${x1} ${y1} Q ${mx} ${my} ${x2} ${y2}" fill="none" stroke="${color}"
    stroke-width="${wdt}" stroke-linecap="round"/>`;
}

const ring = (cx, cy, r, color, wdt = 10) =>
  `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${color}" stroke-width="${wdt}"/>`;

// ── the thirteen ────────────────────────────────────────────────────────────
// Each returns the art for its category. Subject right, left kept clear.
const SCENES = {
  // Baskets are the hero, so they are drawn large; the sun is always offset
  // from the basket rather than behind it, because overlapping the two turns
  // the chains to mush at card size.
  'getting-started': () => sun(548, 150, 76) + hill() + pine(506, 372, 88) + pine(846, 360, 66)
    + `<path d="M430 ${H} Q 576 436 664 352" fill="none" stroke="${PEACH}" stroke-width="30" stroke-linecap="round"/>`
    + basket(596, 108, 0.96),

  'form-technique': () => sun(534, 146, 74) + hill()
    + flight(452, 404, 716, 268, -130, 'rgba(252,100,20,0.30)', 8)
    + flight(452, 404, 700, 250, -104, ORANGE, 12)
    + basket(624, 96, 0.92) + disc(700, 250, 40),

  putting: () => hill(400)
    + ring(672, 236, 214, 'rgba(32,32,32,0.10)', 18)
    + ring(672, 236, 150, 'rgba(252,100,20,0.26)', 16)
    + basket(560, 84, 1.12) + disc(672, 330, 36),

  driving: () => sun(516, 132, 70) + hill(336)
    + flight(400, 404, 792, 226, -168, ORANGE, 13)
    + pine(470, 358, 78) + pine(858, 348, 62)
    + basket(676, 104, 0.76) + disc(792, 226, 32),

  approach: () => sun(528, 148, 72) + hill()
    + flight(470, 400, 690, 318, -84, ORANGE, 12)
    + basket(600, 104, 0.94) + disc(690, 320, 34),

  forehand: () => sun(530, 146, 74) + hill()
    + flight(452, 404, 706, 258, 140, ORANGE, 12)
    + basket(616, 100, 0.92) + disc(706, 258, 38),

  'disc-selection': () => hill(404)
    + basket(760, 150, 0.52)
    + disc(506, 318, 84, INK, 30) + disc(506, 302, 84, ORANGE, 30)
    + disc(632, 342, 74, INK, 26) + disc(632, 328, 74, PEACH, 26)
    + disc(742, 360, 64, INK, 23) + disc(742, 348, 64, GREEN, 23),

  'course-strategy': () => hill(304)
    + `<path d="M404 ${H} Q 508 402 618 400 Q 754 396 742 306" fill="none" stroke="${PEACH}"
        stroke-width="26" stroke-linecap="round" stroke-dasharray="4 42"/>`
    + pine(474, 372, 96) + pine(566, 388, 74) + pine(858, 358, 84)
    + basket(658, 92, 0.78),

  'mental-game': () => hill(400)
    + ring(668, 232, 224, 'rgba(32,32,32,0.08)', 16)
    + ring(668, 232, 166, 'rgba(32,32,32,0.13)', 16)
    + ring(668, 232, 110, 'rgba(252,100,20,0.28)', 16)
    + basket(586, 96, 0.84),

  // Sun, hill, and a rising arc that passes CLEAR of the basket. An earlier
  // version ran the arc straight through the chains and read as a mistake.
  'fitness-warmup': () => sun(800, 146, 84) + hill()
    + flight(452, 404, 792, 236, 96, ORANGE, 13)
    + basket(500, 118, 0.86),

  'tournament-competition': () => sun(524, 138, 76) + hill()
    + `<rect x="620" y="268" width="128" height="124" fill="${INK}"/>`
    + `<rect x="504" y="318" width="112" height="74" fill="#3d3d3d"/>`
    + `<rect x="752" y="336" width="112" height="56" fill="#3d3d3d"/>`
    + basket(624, 78, 0.48) + disc(560, 302, 32) + disc(808, 320, 28, PEACH),

  'rules-etiquette': () => hill()
    + `<rect x="770" y="150" width="15" height="242" fill="${INK}"/>`
    + `<path d="M770 156 L876 190 L770 224 Z" fill="${ORANGE}"/>`
    + basket(470, 122, 0.88) + disc(660, 388, 34, PEACH),

  // Field work: a line of discs thrown at one basket, all flat on the ground.
  practice: () => hill(368)
    + basket(636, 124, 0.92)
    + [0, 1, 2, 3].map((i) => disc(404 + i * 88, 424 + i * 8, 54 - i * 5,
      i === 3 ? ORANGE : INK, (54 - i * 5) * 0.33)).join(''),
};

const svg = (body) => `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}"
  viewBox="0 0 ${W} ${H}"><rect width="${W}" height="${H}" fill="${PEACH}"/>${body}</svg>`;

(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const slugs = Object.keys(SCENES);
  for (const slug of slugs) {
    const buf = Buffer.from(svg(SCENES[slug]()));
    const file = path.join(OUT, slug + '.webp');
    await sharp(buf).resize(W, H).webp({ quality: 88 }).toFile(file);
    const kb = Math.round(fs.statSync(file).size / 1024);
    console.log('  ' + slug.padEnd(24) + W + 'x' + H + '  ' + kb + ' KB');
  }
  const total = slugs.reduce((n, s) => n + fs.statSync(path.join(OUT, s + '.webp')).size, 0);
  console.log(`\n${slugs.length} cards, ${Math.round(total / 1024)} KB total -> ${path.relative(process.cwd(), OUT)}`);
})();
